"{
  "name": "my-animation",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build"
  },
  "dependencies": {
    "@motion-canvas/2d": "^3.17.0",
    "@motion-canvas/core": "^3.17.0"
  },
  "devDependencies": {
    "@motion-canvas/ui": "^3.17.0",
    "@motion-canvas/vite-plugin": "^3.17.0",
    "typescript": "^5.0.0",
    "vite": "^5.0.0"
  }
}
"

"import {defineConfig} from 'vite';
import motionCanvas from '@motion-canvas/vite-plugin';

export default defineConfig({
  plugins: [
    motionCanvas(),
  ],
});
"

"import {makeProject} from '@motion-canvas/core';

import radius from './scenes/radius?scene';

export default makeProject({
  scenes: [radius],
});
"

"import {makeScene2D, Circle, Txt} from '@motion-canvas/2d';
import {createRef, waitFor, easeInOutCubic} from '@motion-canvas/core';

export default makeScene2D(function* (view) {
  const pipe = createRef<Circle>();
  const insulation = createRef<Circle>();
  const text = createRef<Txt>();
  const heatText = createRef<Txt>();

  view.add(
    <>
      <Circle
        ref={insulation}
        width={200}
        height={200}
        fill="#e74c3c"
        opacity={0.5}
      />
      <Circle
        ref={pipe}
        width={200}
        height={200}
        fill="#34495e"
      />
      <Txt
        ref={text}
        y={-300}
        fill="#ffffff"
        fontSize={48}
        text="Critical Radius of Insulation (r_c = k / h)"
      />
      <Txt
        ref={heatText}
        y={300}
        fill="#ffffff"
        fontSize={40}
        text="Bare Pipe (No Insulation)"
        textAlign="center"
      />
    </>
  );

  // 1. Initial State
  yield* waitFor(1);

  // 2. Growing insulation UP to Critical Radius
  yield* heatText().text("Adding Insulation (Below Critical Radius)\nHeat Loss INCREASES!", 1);
  yield* insulation().size(400, 2, easeInOutCubic);

  yield* waitFor(1);
  yield* heatText().text("Critical Radius Reached (r = r_c)\nHeat Loss is at MAXIMUM", 1);
  yield* insulation().fill("#f1c40f", 0.5); // Turn yellow to show danger/maximum heat loss

  yield* waitFor(2);

  // 3. Growing insulation PAST Critical Radius
  yield* insulation().fill("#2ecc71", 0.5); // Turn green to show it's finally working
  yield* heatText().text("Adding Insulation (Above Critical Radius)\nHeat Loss finally DECREASES", 1);
  yield* insulation().size(800, 2, easeInOutCubic);

  yield* waitFor(3);
});
"

